import{_ as t,o as e,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"2-安装和配置FastDFS","description":"","frontmatter":{"title":"2-安装和配置FastDFS","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/2-安装和配置FastDFS.md","filePath":"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/2-安装和配置FastDFS.md"}'),a={name:"posts/java快速入门/第九部分：微服务/02-实战-乐优商城/分布式文件系统FastDFS安装教程/2-安装和配置FastDFS.md"};function c(d,s,f,p,l,n){return e(),o("div",null,[...s[0]||(s[0]=[r("<div><ul><li>==进入目录：====cd fastdfs-5.11==</li><li>==执行编译：====./make.sh==</li><li>==安装：====./make.sh install==</li></ul><p><code>==查看可执行命令：====ls -la /usr/bin/fdfs*==</code></p><p>- 校验安装结果 1）安装完成，我们应该能在<code>/etc/init.d/</code>目录，通过命令<code>ll /etc/init.d/ | grep fdfs</code>看到FastDFS提供的启动脚本：</p><ul><li>其中：</li><li>- <code>fdfs_trackerd</code> 是tracker启动脚本</li><li>- <code>fdfs_storaged</code> 是storage启动脚本</li><li>2）我们可以在 <code>/etc/fdfs</code>目录，通过命令查看到以下配置文件模板：</li></ul><p>其中： - <code>tarcker.conf.sample</code> 是tracker的配置文件模板 - <code>storage.conf.sample</code> 是storage的配置文件模板 - <code>client.conf.sample</code> 是客户端的配置文件模板 将以下两个文件进行复制操作： cp /usr/local/src/fastdfs/conf/http.conf /etc/fdfs/ #供nginx访问使用￼cp /usr/local/src/fastdfs/conf/mime.types /etc/fdfs/ #供nginx访问使用</p><p><strong>一、配置<strong><strong>Tracker</strong></strong>服务</strong></p><p>==进入====/etc/fdfs====目录，通过====cp====命令拷贝====tracker.conf.sample====，删除====.sample====后缀作为正式文件：==</p><p>==编辑====tracker.conf====：====vi tracker.conf====，修改相关参数====￼====#====需要修改的内容如下==</p><p>==port=22122== ==# tracker====服务器端口（默认====22122,====一般不修改）== ==base_path=/home/dfs== ==#== ==存储日志和数据的根目录==</p><p>==如需启动====tracker====，可使用以下方法：（支持====start|stop|restart====）：====￼====使用：====/usr/bin/fdfs_trackerd /etc/fdfs/tracker.conf start==</p><p>或使用 <code>sh /etc/init.d/fdfs_trackerd</code> 启动；；不过安装过程中，fdfs已经被设置为系统服务，我们可以采用熟悉的服务启动方式： sudo service fdfs_trackerd start # 启动fdfs_trackerd服务，停止用stop</p><ul><li>另外，我们可以通过以下命令，设置tracker开机启动：</li><li>sudo chkconfig fdfs_trackerd on</li></ul><p>根据需要可为启动脚本创建软引用，因为<code>fdfs_trackerd</code>等命令在<code>/usr/local/bin</code>中并没有，而是在<code>/usr/bin</code>路径下： <code>ln -s /usr/bin/fdfs_trackerd</code></p><ul><li>/usr/local/bin</li><li>ln -s /usr/bin/stop.sh</li><li>/usr/local/bin</li><li>ln -s /usr/bin/restart.sh</li></ul><p><code>/usr/local/bin</code></p><p><code>其它命令：查看端口情况：netstat -apn|grep fdfs</code></p><p>==可能遇到的报错：== ==/usr/bin/fdfs_trackerd:== ==error== ==while loading shared libraries: libfastcommon.so: cannot open shared object file: No such file or directory====￼== ==解决方案：建立====libfastcommon.so====软链接== ==ln -s /usr/lib64/libfastcommon.so /usr/local/====lib/====libfastcommon.so====￼====ln -s /usr/lib64/libfastcommon.so /usr/====lib/====libfastcommon.so==</p><p><strong>二、配置<strong><strong>Storage</strong></strong>服务</strong></p><p>==进入====/etc/fdfs====目录，有====cp====命令拷贝====storage.conf.sample====，删除====.sample====后缀作为正式文件；==</p><p>==编辑====storage.conf====：====vi storage.conf====，修改相关参数，====需要修改的内容如下：====￼====port=23000== ==# storage====服务端口（默认====23000,====一般不修改）==</p><p>==base_path=/home/dfs== ==#== ==数据和日志文件存储根目录== ==store_path0=/home/dfs== ==#== ==第一个存储目录== ==tracker_server=192.168.52.1:22122== ==# tracker====服务器====IP====和端口== ==http.server_port=8888== ==# http====访问文件的端口====(====默认====8888,====看情况修改====,====和====nginx====中保持一致====)==</p><p>==如需启动====storage====，可执行以下操作（支持====start|stop|restart====）：====￼====/usr/bin/fdfs_storaged /etc/fdfs/storage.conf start==</p><p>也可以使用 <code>sh /etc/init.d/fdfs_storaged</code> 启动，同样我们可以用服务启动方式： sudo service fdfs_storaged start  # 启动fdfs_storaged服务，停止用stop</p><p>另外，我们可以通过以下命令，设置tracker开机启动：</p><p>sudo chkconfig fdfs_storaged on</p><p>==查看====storage====启动日志：进入刚刚指定的====base_path(/home/mm/fastdfs/storage)====中有个====logs====目录，查看====storage.log====文件==</p><p>==此时再查看====tracker====日志：发现已经开始选举，并且作为唯一的一个====tracker====，被选举为====leader==</p><p><code>==查看端口情况：====netstat -apn|grep fdfs==</code></p><p>==通过====monitor====来查看====storage====是否成功绑定：====￼====/usr/bin/fdfs_monitor /etc/fdfs/storage.conf====￼==</p></div>",1)])])}const g=t(a,[["render",c]]);export{_ as __pageData,g as default};
